function validate([houses, heaters]) {
  if (houses.length < 1 || houses.length > 30000) return 'houses needs 1 to 30000 positions.';
  if (heaters.length < 1 || heaters.length > 30000) return 'heaters needs 1 to 30000 positions.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1000000000;
  if (!houses.every(ok) || !heaters.every(ok)) return 'Each position is between 1 and 10^9.';
  return null;
}

