function findRadius(houses, heaters) {
  heaters.sort((a, b) => a - b);
  let radius = 0;
  for (const house of houses) {
    let left = 0;
    let right = heaters.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (heaters[mid] < house) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    const after = left < heaters.length ? heaters[left] - house : Infinity;
    const before = left > 0 ? house - heaters[left - 1] : Infinity;
    radius = Math.max(radius, Math.min(before, after));
  }
  return radius;
}

