function findRadius(houses, heaters) {
  let worst = 0;
  for (const h of houses) {
    let best = Math.abs(h - heaters[0]);
    for (const x of heaters) best = Math.min(best, Math.abs(h - x));
    worst = Math.max(worst, best);
  }
  return worst;
}

