function generate(rand, size) {
  const top = size === 'large' || rand() < 0.2 ? 1000000000 : 20;
  const list = most => Array.from({ length: size === 'large' ? most : 1 + Math.floor(rand() * Math.min(most, 8)) }, () => 1 + Math.floor(rand() * top));
  return size === 'large' ? [list(2000), list(2000)] : [list(8), list(rand() < 0.5 ? 2 : 6)];
}
